-- Squash, surfing, tenis stołowy, taekwondo, tenis, siatkówka halowa, podnoszenie ciężarów, zapasy –
-- tablice kwot LA28 i kalendarze. Można uruchomić ponownie.
-- Źródła: systemy kwalifikacji WSF, ISA, ITTF, World Taekwondo, ITF, FIVB, IWF i UWW dla LA28;
-- wyniki Igrzysk Azjatyckich 2026 i mistrzostw kontynentów w siatkówce 2026.

update public.dyscypliny set opis_kafla = v.opis from (values
  ('squash', 'Nowość · kobiety i mężczyźni · 16 miejsc'),
  ('surfing', 'Kobiety i mężczyźni · 24 miejsca · WSG 2028'),
  ('tenis-stolowy', 'Single, deble, mikst i drużyny mieszane'),
  ('taekwondo', '4 kategorie kobiet i 4 mężczyzn · ranking WT 01.2028'),
  ('tenis', 'Single, deble i mikst · ranking 12.06.2028'),
  ('siatkowka-halowa', 'Mężczyźni: Polska zakwalifikowana (mistrz Europy 2026)'),
  ('podnoszenie-ciezarow', '6 kategorii kobiet i 6 mężczyzn · ranking IWF'),
  ('zapasy', 'Styl wolny, klasyczny i kobiety · MŚ 2027 w Las Vegas')
) as v(slug, opis) where dyscypliny.slug = v.slug;

